import{_ as e,o as i,c as d,ag as n}from"./chunks/framework.D9ghT4bC.js";const c=JSON.parse('{"title":"Unit-related JSON files","description":"","frontmatter":{},"headers":[],"relativePath":"Modders/Mod-file-structure/4-Unit-related-JSON-files.md","filePath":"Modders/Mod-file-structure/4-Unit-related-JSON-files.md"}'),r={name:"Modders/Mod-file-structure/4-Unit-related-JSON-files.md"};function o(a,t,s,h,l,u){return i(),d("div",null,[...t[0]||(t[0]=[n('<h1 id="unit-related-json-files" tabindex="-1">Unit-related JSON files <a class="header-anchor" href="#unit-related-json-files" aria-label="Permalink to &quot;Unit-related JSON files&quot;">​</a></h1><h2 id="units-json" tabindex="-1">Units.json <a class="header-anchor" href="#units-json" aria-label="Permalink to &quot;Units.json&quot;">​</a></h2><p><a href="https://github.com/yairm210/Unciv/blob/master/android/assets/jsons/Civ%20V%20-%20Gods%20%26%20Kings/Units.json" target="_blank" rel="noreferrer">Link to original</a></p><p>This file should contain a list of all the units, both military and civilian, that you want to use in your mod.</p><p>Each unit has the following structure:</p><table tabindex="0"><thead><tr><th>Attribute</th><th>Type</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td>name</td><td>String</td><td>Required</td><td></td></tr><tr><td>unitType</td><td>String</td><td>Required</td><td>The type of the unit. Must be in <a href="#unittypesjson">UnitTypes.json</a></td></tr><tr><td>cost</td><td>Integer</td><td>-1</td><td>The amount of production required to build this unit. The production needed is always positive</td></tr><tr><td>movement</td><td>Integer</td><td>0</td><td>The amount of movement points the unit has by</td></tr><tr><td>strength</td><td>Integer</td><td>0</td><td>The melee attack and defensive strength of the unit. If this and rangedStrength are omitted or 0, the unit will be a civilian</td></tr><tr><td>rangedStrength</td><td>Integer</td><td>0</td><td>The ranged attack and defensive strength of the unit. If omitted, the unit cannot ranged attack. If used, strength must be set too.</td></tr><tr><td>religiousStrength</td><td>Integer</td><td>0</td><td>The religious attack and defensive strength of the unit</td></tr><tr><td>range</td><td>Integer</td><td>2</td><td>The range from which ranged attacks can be preformed</td></tr><tr><td>interceptRange</td><td>Integer</td><td>0</td><td>Air units attacking within in this range will be intercepted</td></tr><tr><td>requiredTech</td><td>String</td><td>none</td><td>The tech required to build this unit. Must be in <a href="./2-Civilization-related-JSON-files.html#techsjson">Techs.json</a></td></tr><tr><td>obsoleteTech</td><td>String</td><td>none</td><td>After researching this tech, the unit can no longer be build. Must be in <a href="./2-Civilization-related-JSON-files.html#techsjson">Techs.json</a></td></tr><tr><td>requiredResource</td><td>String</td><td>none</td><td>Resource that is consumed by building this unit. Must be in <a href="./3-Map-related-JSON-files.html#tileresourcesjson">TileResources.json</a></td></tr><tr><td>upgradesTo</td><td>String</td><td>none</td><td>Unit that this unit can upgrade to when it is available. Must be in <a href="#unitsjson">Units.json</a></td></tr><tr><td>replaces</td><td>String</td><td>none</td><td>If this unit is unique to a nation, this is the unit it replaces. Must be in <a href="#unitsjson">Units.json</a></td></tr><tr><td>uniqueTo</td><td>String</td><td>none</td><td>The nation that this unit is unique to. Must be in <a href="./2-Civilization-related-JSON-files.html#nationsjson">Nations.json</a></td></tr><tr><td>hurryCostModifier</td><td>Integer</td><td>0</td><td>If this unit is bought for gold, its price is increased by so much percent</td></tr><tr><td>promotions</td><td>List of Strings</td><td>empty</td><td>A list of all the promotions the unit automatically receives upon being built. Each promotion must be in <a href="#unitpromotionsjson">UnitPromotions.json</a></td></tr><tr><td>uniques</td><td>List of Strings</td><td>empty</td><td>List of <a href="./../uniques.html">unique abilities</a> this unit has</td></tr><tr><td>replacementTextForUniques</td><td>String</td><td>none</td><td>If provided, this will be displayed instead of the list of uniques. Can be used for better formatting.</td></tr><tr><td>attackSound</td><td>String</td><td>none</td><td>The sound that will be played when the unit attacks, and if there isn&#39;t already a sound named by the unit&#39;s name. For possible values, see <a href="./../Images-and-Audio.html#sounds">Sounds</a></td></tr><tr><td>civilopediaText</td><td>List</td><td>empty</td><td>See <a href="./5-Miscellaneous-JSON-files.html#civilopedia-text">civilopediaText chapter</a></td></tr></tbody></table><h2 id="unitpromotions-json" tabindex="-1">UnitPromotions.json <a class="header-anchor" href="#unitpromotions-json" aria-label="Permalink to &quot;UnitPromotions.json&quot;">​</a></h2><p><a href="https://github.com/yairm210/Unciv/blob/master/android/assets/jsons/Civ%20V%20-%20Gods%20%26%20Kings/UnitPromotions.json" target="_blank" rel="noreferrer">Link to original</a></p><p>This file lists the available unit promotions.</p><p>Each promotion must have an icon, except progressions ending in &quot; I&quot;, &quot; II&quot;, &quot; III&quot; (no IV V VI allowed) are rendered by looking up an icon without those suffixes and adding stars.</p><p>Remember, promotions can be &quot;bought&quot; with XP, but also granted by the unit type, buildings, wonders and such. They are preserved when a unit upgrades, therefore special properties of nation unique units that can be inherited when they upgrade should be in a promotion, not uniques/stats in the units json (example: Slinger withdraw).</p><p>Each promotion has the following structure:</p><table tabindex="0"><thead><tr><th>Attribute</th><th>Type</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td>name</td><td>String</td><td>Required</td><td>See above for &quot;I, II, III&quot; progressions</td></tr><tr><td>prerequisites</td><td>List of Strings</td><td>empty</td><td>Prerequisite promotions</td></tr><tr><td>column</td><td>Integer</td><td>Optional</td><td>Determines placement order on the promotion picker screen. Name is historical, these coordinates no longer control placement directly. Promotions without coordinates are ensured to be placed last. (…)</td></tr><tr><td>row</td><td>Integer</td><td>Optional</td><td>… In base mods without any coordinates, promotions without prerequisites are sorted alphabetically and placed top down, the rest of the screen will structure the dependencies logically. If your mod has a &quot;Heal instantly&quot;, it is suggested to use row=0 to place it on top</td></tr><tr><td>unitTypes</td><td>List of Strings</td><td>empty</td><td>The unit types for which this promotion applies as specified in <a href="#unittypesjson">UnitTypes.json</a></td></tr><tr><td>uniques</td><td>List of Strings</td><td>empty</td><td>List of <a href="./../uniques.html">unique abilities</a> this promotion grants to the units</td></tr><tr><td>civilopediaText</td><td>List</td><td>empty</td><td>See <a href="./5-Miscellaneous-JSON-files.html#civilopedia-text">civilopediaText chapter</a></td></tr><tr><td>innerColor</td><td>List</td><td>empty</td><td>Color of the <em>icon</em></td></tr><tr><td>outerColor</td><td>List</td><td>empty</td><td>Color of the <em>background</em></td></tr></tbody></table><h2 id="unittypes-json" tabindex="-1">UnitTypes.json <a class="header-anchor" href="#unittypes-json" aria-label="Permalink to &quot;UnitTypes.json&quot;">​</a></h2><p><a href="https://github.com/yairm210/Unciv/blob/master/android/assets/jsons/Civ%20V%20-%20Gods%20%26%20Kings/UnitTypes.json" target="_blank" rel="noreferrer">Link to original</a></p><p>This optional file is used for defining new types of units. The names of these can be used in unitFilters, and these types determine what domain the unit moves in: over land, over water or through the air. For base ruleset Mods, if the file is omitted or contains an empty list, <a href="https://github.com/yairm210/Unciv/blob/master/android/assets/jsons/Civ%20V%20-%20Vanilla/UnitTypes.json" target="_blank" rel="noreferrer">all types from the Vanilla ruleset</a> are automatically added: Civilian, Melee, Ranged, Scout, Mounted, Armor, Siege, WaterCivilian, WaterMelee, WaterRanged, WaterSubmarine, WaterAircraftCarrier, Fighter, Bomber, AtomicBomber, and Missile.</p><p>Each unit type has the following structure:</p><table tabindex="0"><thead><tr><th>Attribute</th><th>Type</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td>name</td><td>String</td><td>Required</td><td></td></tr><tr><td>movementType</td><td>Enum</td><td>Required</td><td>The domain through which the unit moves. Allowed values: &quot;Water&quot;, &quot;Land&quot;, &quot;Air&quot;</td></tr><tr><td>uniques</td><td>List of String</td><td>none</td><td>List of <a href="./../uniques.html">unique abilities</a> this promotion grants to units of this type</td></tr><tr><td>civilopediaText</td><td>List</td><td>empty</td><td>See <a href="./5-Miscellaneous-JSON-files.html#civilopedia-text">civilopediaText chapter</a></td></tr></tbody></table><h2 id="unitnamegroups-json" tabindex="-1">UnitNameGroups.json <a class="header-anchor" href="#unitnamegroups-json" aria-label="Permalink to &quot;UnitNameGroups.json&quot;">​</a></h2><p><a href="https://github.com/yairm210/Unciv/blob/master/android/assets/jsons/Civ%20V%20-%20Gods%20%26%20Kings/UnitNameGroups.json" target="_blank" rel="noreferrer">Link to original</a></p><p>Provides a list of names that can be applied to units. Once a name it taken, it will not be applied again.</p><p>Each Unit Name Group has the following structure:</p><table tabindex="0"><thead><tr><th>Attribute</th><th>Type</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td>name</td><td>String</td><td>Required</td><td>A unique name for the unit name group (example: Scientist)</td></tr><tr><td>names</td><td>List of String</td><td>Required</td><td>A list of names that can be applied to the group (example: Alan Turing)</td></tr><tr><td>uniques</td><td>List of String</td><td>none</td><td>List of <a href="./../uniques.html#triggerable-uniques">triggerable uniques</a> that are applied to the unit on creation</td></tr><tr><td>civilopediaText</td><td>List</td><td>empty</td><td>See <a href="./5-Miscellaneous-JSON-files.html#civilopedia-text">civilopediaText chapter</a></td></tr></tbody></table>',23)])])}const m=e(r,[["render",o]]);export{c as __pageData,m as default};
